import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.min
import kotlin.system.exitProcess

// square root of an int
fun sqrti(b: Long): Long {
    val n = 2L
    if (b < 2L) {
        return b
    }
    val n1 = n - 1
    val n2 = n
    val n3 = n1
    var c = 1L
    var d = (n3 + b) / n2
    var e = (n3 * d + b / d.toDouble().pow(n1.toInt()).toLong()) / n2
    while (c != d && c != e) {
        c = d
        d = e
        e = (n3 * e + b / e.toDouble().pow(n1.toInt()).toLong()) / n2
    }
    return if (d < e) d else e
}

data class LongRange(val start: Long, val end: Long)

class Rects private constructor(
    private val area: Long,
    private val rw: LongRange,
    private val rh: LongRange,
    private var w: Long
) : Iterator<Pair<Long, Long>> {

    companion object {
        fun new(area: Long): Rects {
            val q = sqrti(area)
            return Rects(area, LongRange(1L, q), LongRange(1L, area), q)
        }

        fun withLimits(area: Long, rw: LongRange, rh: LongRange): Rects {
            val q = sqrti(area)
            val maxw = min(q, min(area / rh.start, rw.end))
            val minw = maxOf(area / rh.end, rw.start)
            return Rects(area, LongRange(minw, maxw), rh, maxw)
        }
    }

    override fun hasNext(): Boolean {
        var tempW = w
        while (tempW >= rw.start) {
            val h = area / tempW
            if (h >= rh.start && h <= rh.end && h * tempW == area) {
                return true
            }
            tempW--
        }
        return false
    }

    override fun next(): Pair<Long, Long> {
        while (w >= rw.start) {
            val currentW = w
            w -= 1
            val h = area / currentW
            if (h < rh.start || h > rh.end || h * currentW != area) {
                continue
            }
            return Pair(currentW, h)
        }
        throw NoSuchElementException()
    }
}

fun solve(a: Long, b: Long): Long? {
    if (a < 1L || b < 1L) {
        return null
    }
    val area = a + b
    val outerRects = Rects.new(area)
    for ((ow, oh) in outerRects) {
        val perimeter = (ow + oh) * 2
        val innerA = Rects.withLimits(a, LongRange(1L, ow), LongRange(1L, oh))
        val innerB = Rects.withLimits(b, LongRange(1L, ow), LongRange(1L, oh))

        var found = false
        run {
            for ((iw, ih) in innerA) {
                if (iw <= ow && ih <= oh) {
                    found = true
                    return perimeter
                }
            }
        }
        run {
            for ((iw, ih) in innerB) {
                if (iw <= ow && ih <= oh) {
                    found = true
                    return perimeter
                }
            }
        }
        if (found) {
            return perimeter
        }
    }
    return null
}

fun input(): Result<Pair<Long, Long>> {
    return try {
        val reader = BufferedReader(InputStreamReader(System.`in`))
        val row = reader.readLine() ?: return Result.failure(Exception("Cannot read stdin"))
        val words = row.trim().split(' ')
        val a = words[0].toLong()
        val b = words[1].toLong()
        Result.success(Pair(a, b))
    } catch (e: Exception) {
        Result.failure(Exception("Cannot parse input"))
    }
}

